"use client";
import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence, useInView, useScroll, useTransform } from "framer-motion";
import {
  MessageSquare, Code2, Eye, Globe, Brain, Mic, FileText,
  Image as ImageIcon, Microscope, Check, Plus, Star, Send, Zap, ArrowRight
} from "lucide-react";


// ══════════════════════════════════════════════════════════════════
//  GLOBAL KEYFRAME STYLES  (injected once into <head>)
// ══════════════════════════════════════════════════════════════════
const KEYFRAMES = `
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');
*,*::before,*::after{box-sizing:border-box;-webkit-font-smoothing:antialiased}
html,body{overflow-x:hidden!important;scroll-behavior:smooth}
@keyframes marquee-l{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@keyframes marquee-r{from{transform:translateX(-50%)}to{transform:translateX(0)}}
@keyframes orb1{0%,100%{transform:translate(0,0) scale(1)}33%{transform:translate(80px,-60px) scale(1.2)}66%{transform:translate(-30px,70px) scale(.9)}}
@keyframes orb2{0%,100%{transform:translate(0,0) scale(1)}40%{transform:translate(-70px,50px) scale(1.3)}70%{transform:translate(40px,-40px) scale(.85)}}
@keyframes orb3{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(-40px,-80px) scale(1.15)}}
@keyframes orb4{0%,100%{transform:translate(0,0) scale(1)}40%{transform:translate(60px,40px) scale(1.1)}70%{transform:translate(-20px,-30px) scale(.92)}}
@keyframes tdot{0%,80%,100%{transform:scale(.65);opacity:.4}40%{transform:scale(1);opacity:1}}
@keyframes gold-glow{0%,100%{box-shadow:0 0 20px rgba(251,191,36,.15),0 0 50px rgba(124,58,237,.1),inset 0 0 0 1px rgba(251,191,36,.25)}50%{box-shadow:0 0 40px rgba(251,191,36,.35),0 0 90px rgba(124,58,237,.2),inset 0 0 0 1px rgba(251,191,36,.5)}}
@keyframes star-grid{0%{opacity:.014}50%{opacity:.025}100%{opacity:.014}}
.tdot{display:inline-block;width:7px;height:7px;border-radius:50%;background:rgba(168,85,247,.8);animation:tdot 1.3s infinite}
.tdot:nth-child(2){animation-delay:.2s}
.tdot:nth-child(3){animation-delay:.4s}
::-webkit-scrollbar{width:6px;background:#050510}
::-webkit-scrollbar-thumb{background:#7C3AED44;border-radius:3px}
`;

function StyleInjector() {
  return <style dangerouslySetInnerHTML={{ __html: KEYFRAMES }} />;
}


if (typeof window !== 'undefined') {
  window.onerror = (msg, src, line, col, err) => {
    document.body.innerHTML = `<pre style="color:red;padding:20px;white-space:pre-wrap">${msg}\n${src}:${line}:${col}\n${err?.stack}</pre>`;
  };
}


//about section 

const capabilities = [
  { icon: MessageSquare, name: "AI Chat", desc: "Reason, plan, and create in natural conversation", color: "124,58,237" },
  { icon: ImageIcon, name: "Image Generation", desc: "Studio-quality visuals in milliseconds", color: "168,85,247" },
  { icon: Code2, name: "Coding Assistant", desc: "Write and review code like a principal engineer", color: "6,182,212" },
  { icon: Globe, name: "Web Search", desc: "Real-time internet access with attribution", color: "124,58,237" },
  { icon: Eye, name: "Vision", desc: "Understand any image, diagram, or UI instantly", color: "168,85,247" },
  { icon: FileText, name: "Documents", desc: "Analyze entire documents and reports instantly", color: "6,182,212" },
  { icon: Brain, name: "Memory", desc: "Persistent context that never forgets", color: "124,58,237" },
  { icon: Mic, name: "Voice Mode", desc: "Conversational audio that feels natural", color: "168,85,247" },
  { icon: Microscope, name: "Deep Research", desc: "Autonomous agents synthesizing 50+ sources", color: "6,182,212" },
];

const CARD_DIRS = [
  { x: -80, y: 0 },
  { x: 0,   y: 60 },
  { x:  80, y: 0 },
  { x: -80, y: 0 },
  { x: 0,   y: 60 },
  { x:  80, y: 0 },
  { x: -80, y: 0 },
  { x: 0,   y: 60 },
  { x:  80, y: 0 },
];

export function About() {
  const sectionRef = useRef<HTMLDivElement>(null);
  const titleRef = useRef<HTMLDivElement>(null);
  const inView = useInView(titleRef, { once: true, margin: "-80px" });
  const { scrollYProgress } = useScroll({ target: sectionRef, offset: ["start end", "end start"] });
  const y = useTransform(scrollYProgress, [0, 1], [50, -50]);

  return (
    <section
      ref={sectionRef}
      id="about"
      className="relative py-24 border-t border-white/5 overflow-hidden"
      data-testid="section-about"
    >
      <motion.div style={{ y }} className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/3 -left-40 w-80 h-80 rounded-full blur-3xl" style={{ background: "rgba(124,58,237,0.05)" }} />
        <div className="absolute bottom-1/3 -right-40 w-80 h-80 rounded-full blur-3xl" style={{ background: "rgba(6,182,212,0.04)" }} />
      </motion.div>

      <div className="container mx-auto px-6 relative z-10">
        <div ref={titleRef} className="max-w-3xl mx-auto text-center mb-14">
          <motion.div
            initial={{ opacity: 0, x: -50 }}
            animate={inView ? { opacity: 1, x: 0 } : {}}
            transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}
            className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-primary/30 bg-primary/5 text-xs font-semibold tracking-widest text-primary/80 uppercase mb-5"
          >
            About Vortis
          </motion.div>

          <motion.h2
            initial={{ opacity: 0, x: 60 }}
            animate={inView ? { opacity: 1, x: 0 } : {}}
            transition={{ duration: 0.8, delay: 0.1, ease: [0.16, 1, 0.3, 1] }}
            className="text-4xl md:text-5xl font-black font-display leading-tight mb-5"
          >
            One platform.{" "}
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary via-secondary to-accent">
              Every capability.
            </span>
          </motion.h2>

          <motion.p
            initial={{ opacity: 0, y: 30, filter: "blur(6px)" }}
            animate={inView ? { opacity: 1, y: 0, filter: "blur(0px)" } : {}}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="text-base text-muted-foreground leading-relaxed"
          >
            Other AI tools make you juggle a dozen tabs. Vortis brings Chat, Images, Code, Search, Vision, Documents, Memory, Voice, and Deep Research into one seamless surface — where everything shares context and amplifies each other.
          </motion.p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mb-12">
          {capabilities.map((cap, i) => {
            const Icon = cap.icon;
            const dir = CARD_DIRS[i];
            return (
              <motion.div
                key={i}
                initial={{ opacity: 0, x: dir.x, y: dir.y }}
                whileInView={{ opacity: 1, x: 0, y: 0 }}
                viewport={{ once: true, margin: "-40px" }}
                transition={{ delay: i * 0.08, duration: 0.65, ease: [0.16, 1, 0.3, 1] }}
                whileHover={{ y: -8, transition: { duration: 0.25 } }}
                className="flex items-start gap-4 p-5 rounded-xl bg-card border border-white/5 overflow-hidden group relative cursor-default"
                style={{ "--cap-color": `rgba(${cap.color},0.35)` } as React.CSSProperties}
                data-testid={`about-cap-${i}`}
              >
                <motion.div
                  className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300"
                  style={{ background: `radial-gradient(circle at 0% 50%, rgba(${cap.color},0.1), transparent 60%)` }}
                />
                <div className="absolute bottom-0 left-0 h-px w-0 group-hover:w-full transition-all duration-500"
                  style={{ background: `linear-gradient(90deg, transparent, rgba(${cap.color},0.6), transparent)` }}
                />
                <div className="absolute inset-0 rounded-xl border border-transparent group-hover:border-[rgba(139,92,246,0.3)] transition-colors duration-300 pointer-events-none" />

                <motion.div
                  className="w-9 h-9 rounded-lg flex items-center justify-center shrink-0 mt-0.5"
                  style={{ background: `rgba(${cap.color},0.12)` }}
                  whileHover={{ rotate: 15, scale: 1.15 }}
                  transition={{ type: "spring", stiffness: 400, damping: 15 }}
                >
                  <Icon className="w-4 h-4" style={{ color: `rgb(${cap.color})` }} />
                </motion.div>
                <div className="relative z-10 min-w-0">
                  <div className="text-sm font-semibold text-white mb-1">{cap.name}</div>
                  <div className="text-xs text-muted-foreground leading-relaxed">{cap.desc}</div>
                </div>
              </motion.div>
            );
          })}
        </div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ delay: 0.3, duration: 0.7 }}
          className="flex items-center justify-center gap-3 text-sm text-muted-foreground"
        >
          <span>Join thousands of researchers, engineers, and creators</span>
          <ArrowRight className="w-4 h-4 text-primary" />
          <a href="#pricing" className="text-primary font-semibold hover:text-secondary transition-colors">
            See plans
          </a>
        </motion.div>
      </div>
    </section>
  );
}






